// Helper function to check if a number is prime
function is_prime(x: int) : bool
    requires x >= 0
{
    if x < 2 then return false;
    var i := 2;
    while i * i <= x
        invariant 2 <= i <= x
        invariant forall j :: 2 <= j < i ==> x % j != 0
    {
        if x % i == 0 {
            return false;
        }
        i := i + 1;
    }
    return true;
}

// Helper function to count the number of primes less than n
function CountPrimesLessThan(n: int) : int
    requires n >= 0
{
    var count := 0;
    var i := 2;
    while i < n
        invariant 0 <= count <= i
        invariant forall j :: 2 <= j < i ==> is_prime(j) ==> count >= CountPrimesLessThan(j)
    {
        if is_prime(i) {
            count := count + 1;
        }
        i := i + 1;
    }
    return count;
}
